def run(scene, robot):
    box = scene.get("white box")
    pens = scene.of_kind("pen")
    cands = [p for p in pens if p.y < box.y]
    if cands:
        pen = min(cands, key=lambda p: abs(p.x - box.x))
    else:
        pen = min(pens, key=lambda p: p.y)
    gap = 2.0
    tx = box.x - box.w/2 - gap - pen.w/2
    ty = box.y
    skip = {box.name, pen.name}
    for o in scene.objects():
        if o.name in skip:
            continue
        if abs(o.x - tx) < (o.w + pen.w)/2 + 4 and abs(o.y - ty) < (o.d + pen.d)/2 + 4:
            robot.move(o, *scene.free_spot(size=(o.w, o.d), clearance=3, avoid=[(tx, ty, pen.w+4, pen.d+4)]))
            box = scene.get(box.name)
            pen = scene.get(pen.name)
            tx = box.x - box.w/2 - gap - pen.w/2
            ty = box.y
    robot.pick(scene.get(pen.name))
    robot.place_next_to(scene.get(box.name), "left_of", gap=gap)

import math
def run(scene, robot):
    refs = scene.with_role("reference")
    if refs:
        box = refs[0]
    else:
        boxes = scene.of_kind("box")
        box = boxes[0] if boxes else scene.get("white box")
    pens = scene.of_kind("pen")
    cands = [p for p in pens if p.y < box.y]
    if cands:
        pen = min(cands, key=lambda o: abs(o.x - box.x))
    else:
        pen = min(pens, key=lambda o: o.y)
    gap = 2.5
    tx = box.x - box.w/2 - gap - pen.w/2
    ty = box.y
    for o in scene.objects():
        if o.name == pen.name or o.name == box.name:
            continue
        if abs(o.x - tx) < (o.w + pen.w)/2 + 4 and abs(o.y - ty) < (o.d + pen.d)/2 + 4:
            robot.move(o, *scene.free_spot(size=(o.w, o.d), clearance=3, avoid=[(tx, ty, pen.w+4, pen.d+4)]))
    box = scene.get(box.name)
    pen = scene.get(pen.name)
    robot.pick(pen)
    robot.place_next_to(box, "left_of", gap=gap)
